const normalize = (s) =>
  (s || '')
    .toString()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '') // saca tildes
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

// distancia real en km entre dos coordenadas (fórmula de Haversine)
const haversineKm = (lat1, lng1, lat2, lng2) => {
  const toRad = (deg) => (deg * Math.PI) / 180;
  const R = 6371; // radio de la Tierra en km
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
};

const resolveDealerCode = (sellerZip, sellerAddress, sellerLat, sellerLng) => {
  const zipNum = parseInt(sellerZip, 10);

  // 1) match exacto por CP
  if (!isNaN(zipNum)) {
    const exact = DEALERS.find((d) => d.cp === zipNum);
    if (exact) return { dealerCode: exact.dealerCode, matchType: 'cp_exacto', dealer: exact.nombre };
  }

  // 2) match por dirección (coincidencia de palabras significativas, ej calle/barrio)
  const addrNorm = normalize(sellerAddress);
  const addrWords = addrNorm.split(' ').filter((w) => w.length > 3); // ignora palabras cortas (av, de, s.a, etc)
  if (addrWords.length) {
    let best = null;
    let bestScore = 0;
    for (const d of DEALERS) {
      const dNorm = normalize(d.direccion);
      const score = addrWords.filter((w) => dNorm.includes(w)).length;
      if (score > bestScore) {
        bestScore = score;
        best = d;
      }
    }
    if (best && bestScore > 0) {
      return { dealerCode: best.dealerCode, matchType: 'direccion', dealer: best.nombre };
    }
  }

  // 3) fallback: dealer geográficamente más cercano (distancia real por lat/lng, Haversine)
  const lat = parseFloat(sellerLat);
  const lng = parseFloat(sellerLng);
  if (!isNaN(lat) && !isNaN(lng)) {
    let nearest = null;
    let minDist = Infinity;
    for (const d of DEALERS) {
      const dist = haversineKm(lat, lng, d.lat, d.lng);
      if (dist < minDist) {
        minDist = dist;
        nearest = d;
      }
    }
    if (nearest) {
      return { dealerCode: nearest.dealerCode, matchType: 'geo_cercano', dealer: nearest.nombre, distanciaKm: Math.round(minDist * 10) / 10 };
    }
  }

  return { dealerCode: '', matchType: 'sin_match', dealer: null };
};

